sys_script.script:
(function executeRule(current, previous) {

    // Check that both dates are available
    if (!current.event_date || !current.registration_deadline) {
        return;
    }

    // Rule 1: Registration Deadline cannot be after Event Date
    if (current.registration_deadline > current.event_date) {

        gs.addErrorMessage(
            "Registration Deadline cannot be after Event Date."
        );

        current.setAbortAction(true);
        return;
    }

    // Rule 2: Event Date cannot be in the past
    var today = new GlideDateTime();
    var eventDate = new GlideDateTime(current.event_date);

    if (eventDate.before(today)) {

        gs.addErrorMessage(
            "Event Date cannot be in the past."
        );

        current.setAbortAction(true);
        return;
    }

    // Rule 3: Registration Deadline cannot be in the past
    var deadlineDate =
        new GlideDateTime(current.registration_deadline);

    if (deadlineDate.before(today)) {

        gs.addErrorMessage(
            "Registration Deadline cannot be in the past."
        );

        current.setAbortAction(true);
        return;
    }

})(current, previous);
